mapper.select:
select c.class_id, c.class_cd, c.class_nm, c.sort_no, c.use_yn, c.remark, c.row_ver,
       (select count(*) from mst_equip e where e.class_id = c.class_id and e.use_yn = 'Y') as equip_cnt
  from mst_equip_class c where c.class_id = #{classId}

mapper.update:
update mst_equip_class set class_cd = #{f.classCd}, class_nm = #{f.classNm}, sort_no = #{f.sortNo}, use_yn = #{f.useYn},
                           remark = #{f.remark}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where class_id = #{id} and row_ver = #{f.rowVer}

mapper.sql:
from mst_equip e join mst_equip_class c on c.class_id = e.class_id

    and e.plant_cd = #{q.plantCd}
    and e.class_id = #{q.classId}
    and e.equip_cd like #{q.cdLike} escape '\'
    and e.equip_nm ilike #{q.nmLike} escape '\'
    and e.use_yn = #{q.useYn}

mapper.update:
update mst_equip set plant_cd = #{f.plantCd}, equip_cd = #{f.equipCd}, equip_nm = #{f.equipNm}, class_id = #{f.classId},
                     node_id = #{f.nodeId}, maker = #{f.maker}, model = #{f.model}, serial_no = #{f.serialNo},
                     asset_no = #{f.assetNo}, install_date = #{f.installDate}, use_yn = #{f.useYn}, remark = #{f.remark},
                     row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where equip_id = #{id} and row_ver = #{f.rowVer}

update mst_phys_asset set asset_cd = #{f.assetCd}, asset_type = #{f.assetType}, asset_nm = #{f.assetNm},
                          serial_no = #{f.serialNo}, item_id = #{f.itemId}, life_shots = #{f.lifeShots},
                          calib_cycle_days = #{f.calibCycleDays}, last_calib_date = #{f.lastCalibDate},
                          use_yn = #{f.useYn}, remark = #{f.remark},
                          row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where asset_id = #{id} and row_ver = #{f.rowVer}
